const { exec, execFile } = require('child_process');
const allowedTool = tool === 'conda' ? tool : null;
if (!allowedTool) throw new Error('unsupported executable');
const output = await new Promise((resolve, reject) => {
  execFile(allowedTool, ['env', 'list', '--json'], { ...options, shell: false }, (err, stdout) => {
    if (err) reject(err);
    else resolve(stdout || '');
  });
});
